CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE TABLE "Enterprises" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "BusinessName" character varying(200) NOT NULL,
        "TaxId" character varying(50) NOT NULL,
        "ContactName" character varying(150) NOT NULL,
        "CorporateEmail" character varying(150) NOT NULL,
        "CorporatePhone" character varying(20) NOT NULL,
        "PasswordHash" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_Enterprises" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE TABLE "Clients" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FirstName" character varying(100) NOT NULL,
        "LastName" character varying(100) NOT NULL,
        "Email" character varying(150) NOT NULL,
        "Phone" character varying(20) NOT NULL,
        "PasswordHash" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "IsActive" boolean NOT NULL,
        "EnterpriseId" integer,
        CONSTRAINT "PK_Clients" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Clients_Enterprises_EnterpriseId" FOREIGN KEY ("EnterpriseId") REFERENCES "Enterprises" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE UNIQUE INDEX "IX_Clients_Email" ON "Clients" ("Email");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE INDEX "IX_Clients_EnterpriseId" ON "Clients" ("EnterpriseId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE UNIQUE INDEX "IX_Enterprises_CorporateEmail" ON "Enterprises" ("CorporateEmail");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    CREATE UNIQUE INDEX "IX_Enterprises_TaxId" ON "Enterprises" ("TaxId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929201739_Client&EnterpriseDb') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260929201739_Client&EnterpriseDb', '10.0.12');
    END IF;
END $EF$;
COMMIT;

